=== plan/NightlyPricing.java
     1	package br.com.marealta.plan;
     2	
     3	import br.com.marealta.domain.Money;
     4	import br.com.marealta.domain.Quote;
     5	import br.com.marealta.domain.Season;
     6	import java.math.BigDecimal;
     7	import java.time.LocalDate;
     8	
     9	/** Cálculo por diária, compartilhado pelos planos que cobram noite a noite. */
    10	final class NightlyPricing {
    11	    private static final BigDecimal HIGH_SEASON_FACTOR = new BigDecimal("1.20");
    12	
    13	    private NightlyPricing() {}
    14	
    15	    static BigDecimal nightPrice(BigDecimal rate, LocalDate night) {
    16	        return Season.isHigh(night) ? Money.round(rate.multiply(HIGH_SEASON_FACTOR)) : Money.round(rate);
    17	    }
    18	
    19	    static BigDecimal sumOfNights(BookingRequest r) {
    20	        BigDecimal sum = Money.ZERO;
    21	        for (LocalDate d = r.checkIn(); d.isBefore(r.checkOut()); d = d.plusDays(1)) {
    22	            sum = sum.add(nightPrice(r.room().nightlyRate(), d));
    23	        }
    24	        return sum;
    25	    }
    26	
    27	    static Quote withPercentDiscount(BookingRequest r, int percent) {
    28	        BigDecimal subtotal = sumOfNights(r);
    29	        return Quote.of(r.nights(), subtotal, Money.percent(subtotal, percent));
    30	    }
    31	}
