     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.text.DecimalFormat;
     6	import java.text.DecimalFormatSymbols;
     7	import java.util.Locale;
     8	
     9	/** Aritmética monetária: centavos, arredondamento meio para o par a cada passo. */
    10	public final class Money {
    11	    public static final BigDecimal ZERO = round(BigDecimal.ZERO);
    12	
    13	    private Money() {}
    14	
    15	    public static BigDecimal round(BigDecimal v) {
    16	        return v.setScale(2, RoundingMode.HALF_EVEN);
    17	    }
    18	
    19	    public static BigDecimal percent(BigDecimal base, int percent) {
    20	        return round(base.multiply(BigDecimal.valueOf(percent)).divide(BigDecimal.valueOf(100)));
    21	    }
    22	
    23	    /** R$ 1.234,56 */
    24	    public static String brl(BigDecimal v) {
    25	        DecimalFormatSymbols sym = new DecimalFormatSymbols(Locale.ROOT);
    26	        sym.setGroupingSeparator('.');
    27	        sym.setDecimalSeparator(',');
    28	        return "R$ " + new DecimalFormat("#,##0.00", sym).format(round(v));
    29	    }
    30	
    31	    /** 599.76 */
    32	    public static String plain(BigDecimal v) {
    33	        return round(v).toPlainString();
    34	    }
    35	}
