    22	    private BigDecimal amountPaid = Money.ZERO;
    23	    private BigDecimal refund; // null até o cancelamento
    24	
    25	    public Reservation(int id, Room room, String guestName, String guestEmail, String guestCpf,
    26	                       LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan,
    27	                       Quote quote) {
    28	        this.id = id;
    29	        this.room = room;
    30	        this.guestName = guestName;
    31	        this.guestEmail = guestEmail;
    32	        this.guestCpf = guestCpf;
    33	        this.checkIn = checkIn;
    34	        this.checkOut = checkOut;
    35	        this.guests = guests;
    36	        this.ratePlan = ratePlan;
    37	        this.nights = quote.nights();
    38	        this.subtotal = quote.subtotal();
    39	        this.discount = quote.discount();
    40	        this.total = quote.total();
    41	    }
    42	
    43	    /** Ocupa o quarto em alguma noite do intervalo [from, to)? */
    44	    public boolean overlaps(LocalDate from, LocalDate to) {
    45	        return checkIn.isBefore(to) && from.isBefore(checkOut);
    46	    }
    47	
    48	    public void confirm() {
    49	        status = ReservationStatus.CONFIRMED;
    50	        amountPaid = total;
    51	    }
    52	
    53	    public void startStay() { status = ReservationStatus.CHECKED_IN; }
    54	
    55	    public void finishStay() { status = ReservationStatus.CHECKED_OUT; }
    56	
    57	    public void cancel() {
    58	        refund = ratePlan.refund(amountPaid);
    59	        status = ReservationStatus.CANCELLED;
    60	    }
    61	
    62	    /** Dinheiro que ficou com a pousada: pago menos devolvido. */
    63	    public BigDecimal netRevenue() {
    64	        return refund == null ? amountPaid : amountPaid.subtract(refund);
    65	    }
