     6	public final class Season {
     7	    private Season() {}
     8	
     9	    /** Alta temporada: 15/12 até o fim de fevereiro, e julho inteiro. */
    10	    public static boolean isHigh(LocalDate night) {
    11	        Month m = night.getMonth();
    12	        return m == Month.JANUARY || m == Month.FEBRUARY || m == Month.JULY
    13	                || (m == Month.DECEMBER && night.getDayOfMonth() >= 15);
    14	    }
    15	}

