    26	    private final Map<Integer, Room> rooms = new LinkedHashMap<>();
    27	    private final Map<Integer, Reservation> reservations = new LinkedHashMap<>();
    28	    private final List<Message> messages = new ArrayList<>();
    29	    private int nextReservationId = 1;
    30	    private int nextMessageId = 1;
    31	
    32	    public ReservationService() {
    33	        for (Room r : List.of(
    34	                new Room(101, RoomType.STANDARD, 2, new BigDecimal("249.90")),
    35	                new Room(102, RoomType.STANDARD, 2, new BigDecimal("249.90")),
    36	                new Room(201, RoomType.DELUXE, 3, new BigDecimal("389.90")),
    37	                new Room(202, RoomType.DELUXE, 3, new BigDecimal("389.90")),
    38	                new Room(301, RoomType.SUITE, 4, new BigDecimal("579.90")))) {
    39	            rooms.put(r.number(), r);
    40	        }
    41	    }
    42	
    43	    public synchronized List<Room> rooms() {
    44	        return List.copyOf(rooms.values());
    45	    }
    46	
    47	    public synchronized List<Message> messages() {
    48	        return List.copyOf(messages);
    49	    }
    50	
    51	    public synchronized Reservation create(NewReservation n) {
    52	        if (!n.checkOut().isAfter(n.checkIn())) {
    53	            throw ApiException.invalid("A saída deve ser depois da entrada");
    54	        }
    55	        if (n.guests() < 1) {
    56	            throw ApiException.invalid("É preciso pelo menos um hóspede");
    57	        }
    58	        Room room = rooms.get(n.roomNumber());
    59	        if (room == null) {
    60	            throw new ApiException(404, "ROOM_NOT_FOUND", "Quarto não encontrado");
    61	        }
    62	        Quote quote;
    63	        try {
    64	            quote = n.ratePlan().quote(new BookingRequest(room, n.checkIn(), n.checkOut(), n.companyCode()));
    65	        } catch (PlanRuleException e) {
    66	            throw ApiException.invalid(e.getMessage());
    67	        }
    68	        if (n.guests() > room.capacity()) {
    69	            throw new ApiException(422, "CAPACITY_EXCEEDED", "O quarto comporta no máximo " + room.capacity() + " hóspedes");
    70	        }
    71	        boolean taken = reservations.values().stream().anyMatch(r ->
    72	                r.room().number() == room.number()
    73	                        && r.status() != ReservationStatus.CANCELLED
    74	                        && r.overlaps(n.checkIn(), n.checkOut()));
    75	        if (taken) {
    76	            throw new ApiException(409, "ROOM_UNAVAILABLE", "Quarto já reservado em alguma das noites");
    77	        }
    78	        Reservation res = new Reservation(nextReservationId++, room, n.guestName(), n.guestEmail(), n.guestCpf(),
    79	                n.checkIn(), n.checkOut(), n.guests(), n.ratePlan(), quote);
    80	        reservations.put(res.id(), res);
    81	        return res;
    82	    }
