   130	    public synchronized String occupancyCsv(LocalDate date) {
   131	        List<Reservation> occupying = reservations.values().stream()
   132	                .filter(r -> r.status().isPaid() && !r.checkIn().isAfter(date) && date.isBefore(r.checkOut()))
   133	                .sorted(Comparator.comparingInt((Reservation r) -> r.room().number()).thenComparingInt(Reservation::id))
   134	                .toList();
   135	        StringBuilder sb = new StringBuilder("room,type,reservation,check_in,check_out\n");
   136	        for (Reservation r : occupying) {
   137	            sb.append(r.room().number()).append(',').append(r.room().type()).append(',').append(r.id()).append(',')
   138	                    .append(r.checkIn()).append(',').append(r.checkOut()).append('\n');
   139	        }
   140	        long occupiedRooms = occupying.stream().map(r -> r.room().number()).distinct().count();
   141	        sb.append("total,").append(occupiedRooms).append('/').append(rooms.size()).append('\n');
   142	        return sb.toString();
   143	    }
