   145	    public synchronized String revenueCsv(java.time.YearMonth month) {
   146	        List<Reservation> list = reservations.values().stream()
   147	                .filter(r -> java.time.YearMonth.from(r.checkIn()).equals(month)
   148	                        && r.netRevenue().signum() > 0)
   149	                .sorted(Comparator.comparing(Reservation::checkIn).thenComparingInt(Reservation::id))
   150	                .toList();
   151	        BigDecimal total = Money.ZERO;
   152	        StringBuilder sb = new StringBuilder("reservation,room,check_in,check_out,status,amount\n");
   153	        for (Reservation r : list) {
   154	            sb.append(r.id()).append(',').append(r.room().number()).append(',').append(r.checkIn()).append(',')
   155	                    .append(r.checkOut()).append(',').append(r.status()).append(',')
   156	                    .append(Money.plain(r.netRevenue())).append('\n');
